package chain

import (
	"crypto/ed25519"
	cryptorand "crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
)

// KeyPair is an Ed25519 keypair. A chain's root keypair signs its root
// link; every other keypair is generated by whoever mints a delegation
// token, which embeds the public half in its cnf claim and hands the
// private half to the holder out of band.
//
// The private half is never part of any token's serialized form. That is
// what makes a recipient of the bytes unable to derive from them, and it is
// the property the Biscuit spike identified as genuinely worse in Biscuit,
// where an unsealed token serializes the next signing key.
type KeyPair struct {
	Public  ed25519.PublicKey
	Private ed25519.PrivateKey
}

// GenerateKey returns a fresh Ed25519 keypair, reading entropy from rand. A
// nil rand reads crypto/rand.Reader; tests may pass a deterministic reader
// to get reproducible keys, which is how the committed vectors are
// reproducible.
func GenerateKey(rand io.Reader) (KeyPair, error) {
	if rand == nil {
		rand = cryptorand.Reader
	}
	pub, priv, err := ed25519.GenerateKey(rand)
	if err != nil {
		// ed25519.GenerateKey's own error names only an entropy-source read
		// failure; it carries no key material or caller input, so wrapping
		// it crosses no secret across the package boundary.
		return KeyPair{}, fmt.Errorf("generate ed25519 keypair: %w", err)
	}
	return KeyPair{Public: pub, Private: priv}, nil
}

// confirmation is the RFC 7800 "cnf" claim, carrying the public key whose
// private half must sign this token's children. It is the mechanism that
// lets a holder derive a narrower token offline, with no call to the
// issuer: the parent names the key, so the child's signature is checkable
// by anyone who has already checked the parent's.
type confirmation struct {
	JWK json.RawMessage `json:"jwk"`
}

// okpJWK is an Ed25519 public key as an RFC 8037 OKP JSON Web Key.
//
// The member order is fixed by this struct's declaration order rather than
// left to a map, because the JWK is inside signed bytes: a different order
// is a different token. The order chosen is RFC 8037's own example order,
// which is also what every JOSE library emits.
type okpJWK struct {
	KeyType string `json:"kty"`
	Curve   string `json:"crv"`
	X       string `json:"x"`
}

// JWK key type and curve, as RFC 8037 defines them for Ed25519. Both are
// inputs to signed bytes and are asserted as literals by
// TestFormatConstantsArePinned.
const (
	jwkKeyTypeOKP     = "OKP"
	jwkCurveEd25519   = "Ed25519"
	jwkThumbprintTmpl = `{"crv":"%s","kty":"%s","x":"%s"}`
)

// encodeJWK returns pub as a canonical OKP JWK.
func encodeJWK(pub ed25519.PublicKey) (json.RawMessage, error) {
	if len(pub) != ed25519.PublicKeySize {
		return nil, fmt.Errorf("%w: public key is not an Ed25519 key", ErrInvalidToken)
	}
	raw, err := json.Marshal(okpJWK{
		KeyType: jwkKeyTypeOKP,
		Curve:   jwkCurveEd25519,
		X:       base64.RawURLEncoding.EncodeToString(pub),
	})
	if err != nil {
		return nil, fmt.Errorf("%w: public key cannot be encoded", ErrInvalidToken)
	}
	return raw, nil
}

// decodeJWK reads an OKP JWK back into an Ed25519 public key.
//
// It accepts nothing but the three members encodeJWK emits, with exactly
// those values. A JWK is attacker-supplied data that decides which key
// verifies the next link, so a lenient reader here is the whole
// algorithm-confusion family in one function: a "kty":"oct" with an "x" the
// attacker chose, or an unexpected member a future reader interprets
// differently, must be refused rather than ignored.
func decodeJWK(raw json.RawMessage) (ed25519.PublicKey, error) {
	if err := rejectDuplicateKeys(raw); err != nil {
		return nil, err
	}
	var jwk okpJWK
	if err := strictUnmarshal(raw, &jwk); err != nil {
		return nil, err
	}
	if jwk.KeyType != jwkKeyTypeOKP || jwk.Curve != jwkCurveEd25519 {
		return nil, fmt.Errorf("%w: unsupported key type", ErrInvalidToken)
	}
	pub, err := base64.RawURLEncoding.DecodeString(jwk.X)
	if err != nil || len(pub) != ed25519.PublicKeySize {
		return nil, fmt.Errorf("%w: malformed key", ErrInvalidToken)
	}
	return ed25519.PublicKey(pub), nil
}

// thumbprint returns the RFC 7638 JWK thumbprint of an Ed25519 public key:
// the SHA-256 of the key's required members in lexicographic order, with no
// whitespace, base64url without padding.
//
// Nothing in the wire format carries a thumbprint — there is no kid, by
// design. It exists so a consumer can name a key in its own records, and so
// the format document can state the canonical identifier for a root key
// without implying that a verifier should look one up from a token.
func thumbprint(pub ed25519.PublicKey) (string, error) {
	if len(pub) != ed25519.PublicKeySize {
		return "", fmt.Errorf("%w: public key is not an Ed25519 key", ErrInvalidToken)
	}
	canonical := fmt.Sprintf(jwkThumbprintTmpl,
		jwkCurveEd25519, jwkKeyTypeOKP, base64.RawURLEncoding.EncodeToString(pub))
	sum := sha256.Sum256([]byte(canonical))
	return base64.RawURLEncoding.EncodeToString(sum[:]), nil
}
